//! Language detection and the parser dispatch: a grammar when one is compiled in, the regex tier otherwise.

pub mod grammar;
pub mod literals;
pub mod regex_tier;

use crate::config::settings::Parse;
use crate::model::Symbol;

// `Language`, `Language::name`, `Language::from_name`, `by_extension` and `by_filename`, generated by build.rs from
// languages/registry.toml.
include!(concat!(env!("OUT_DIR"), "/languages_enum.rs"));

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    Grammar,
    Regex,
}

/// The language of a path by its file name (`Makefile`), else by extension; any other file is `Other` with its extension, or `text` when
/// it has none. Whether a file is text at all is decided by its content.
pub fn language_of(path: &str) -> Language {
    let file = path.rsplit('/').next().unwrap_or(path);
    if let Some(language) = by_filename(file) {
        return language;
    }
    let ext = match file.rsplit_once('.') {
        Some((stem, ext))
            if !stem.is_empty()
                && !ext.is_empty()
                && ext.chars().all(|c| c.is_ascii_alphanumeric()) =>
        {
            ext.to_ascii_lowercase()
        }
        _ => return Language::Other("text".into()),
    };
    by_extension(&ext).unwrap_or(Language::Other(ext))
}

pub fn tier(lang: &Language) -> Tier {
    if grammar::grammar_for(lang).is_some() {
        Tier::Grammar
    } else {
        Tier::Regex
    }
}

/// Every definition, reference and literal the parser of `lang` finds in `source`.
pub fn parse(lang: &Language, source: &[u8], rules: &Parse) -> Vec<Symbol> {
    let mut symbols = match grammar::grammar_for(lang) {
        Some(grammar) => {
            let (mut symbols, had_error) = grammar::parse_checked(&grammar, source);
            if had_error && let Ok(text) = std::str::from_utf8(source) {
                // The syntax tree has errors (code caught mid-edit): the grammar may have lost every
                // definition after the broken spot, so add the ones a generic scan still finds.
                for found in regex_tier::parse(text, rules) {
                    let known = symbols
                        .iter()
                        .any(|s| s.role == crate::model::Role::Definition && s.name == found.name);
                    if !known {
                        symbols.push(found);
                    }
                }
            }
            symbols
        }
        None => {
            let prose = rules.prose_extensions.contains(&lang.name());
            std::str::from_utf8(source)
                .map(|text| match prose {
                    true => regex_tier::headings(text),
                    false => regex_tier::parse(text, rules),
                })
                .unwrap_or_default()
        }
    };
    let Ok(text) = std::str::from_utf8(source) else {
        return symbols;
    };
    if *lang == Language::Markdown {
        // Markdown links live in the inline grammar, which the block parse leaves opaque; a line scan
        // finds their targets instead, and prose is not scanned for quoted strings.
        symbols.extend(regex_tier::link_literals(text));
        return symbols;
    }
    let defs: Vec<Symbol> = symbols
        .iter()
        .filter(|s| s.role == crate::model::Role::Definition)
        .cloned()
        .collect();
    for literal in literals::literals(lang, text, &defs) {
        let seen = symbols.iter().any(|s| {
            s.role == crate::model::Role::Literal
                && s.name == literal.name
                && s.line == literal.line
        });
        if !seen {
            symbols.push(literal);
        }
    }
    symbols
}

